const paths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',cameras:'M3 6h13v12H3zM16 10l5-3v10l-5-3',incidents:'M12 3L2 21h20L12 3zM12 9v5M12 17v1',workforce:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',vehicles:'M1 5h13v12H1zM14 9h5l3 4v4h-8M7 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0M21 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',progress:'M3 3v18h18M6 15l5-5 4 3 6-8',reports:'M6 2h9l4 4v16H6zM10 10h5M10 14h5M10 18h5'};
const icon=n=>`<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.reports}"/></svg>`;
Object.assign(paths,{arrow:'M5 12h14M13 6l6 6-6 6',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',expand:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',check:'M5 12l4 4L19 6',close:'M6 6l12 12M6 18L18 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0'});
const views={overview:'Overview',cameras:'Cameras',incidents:'Safety & incidents',workforce:'Workforce',vehicles:'Vehicles & equipment',progress:'Site progress',reports:'Reports'};
const cams=[['Main gate','Gate & access',8,0],['Tower A · North','Structure',32,1],['Tower A · South','Structure',27,2],['Material yard','Storage',14,0],['Equipment zone','Equipment',9,1],['Labour access','Gate & access',12,2],['East perimeter','Perimeter',0,0],['Tower B · Foundation','Structure',24,2]].map((v,i)=>({id:i+1,name:v[0],zone:v[1],people:v[2],image:v[3],online:i!==6}));
const initial=[{id:1042,title:'Possible missing safety helmet',camera:2,severity:'High',status:'Open',time:'10:42',owner:'Safety officer',note:'',history:['10:42 · Sample PPE event created']},{id:1041,title:'Restricted-zone entry',camera:5,severity:'High',status:'Open',time:'10:36',owner:'Site manager',note:'',history:['10:36 · Sample zone event created']},{id:1040,title:'Vehicle congestion at gate',camera:1,severity:'Medium',status:'In review',time:'10:24',owner:'Security supervisor',note:'Gate team reviewing queue.',history:['10:24 · Sample traffic event created','10:28 · Assigned to security']},{id:1039,title:'Safety vest check',camera:4,severity:'Medium',status:'Resolved',time:'09:58',owner:'Safety officer',note:'Supervisor checked the area.',history:['09:58 · Sample PPE event created','10:05 · Resolved by safety officer']}];
let incidents=structuredClone(initial), active='overview',filter='All',search='',camFilter='All',seq=1042;let focusCam=2, cameraLayout='grid', progressMode='compare';
try {const saved=JSON.parse(sessionStorage.getItem('srs-demo-v2')||'null');if(saved){incidents=saved.incidents;seq=Math.max(1042,...incidents.map(e=>e.id));}} catch{}
function persist(){try{sessionStorage.setItem('srs-demo-v2',JSON.stringify({incidents}));}catch{}}
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
const img=i=>`assets/site-${i+1}.jpg`;
const heading=(t,sub,buttons='')=>`<div class="page-heading"><div><div class="eyebrow">Riverside Residences / Site 01</div><h1>${t}</h1><div class="sub">${sub}</div></div><div class="actions">${buttons}</div></div>`;
const badge=(t,cl=t.toLowerCase())=>`<span class="badge ${cl}">${t}</span>`;
const stats=items=>`<div class="stats">${items.map(([a,b,c,d])=>`<div class="stat"><div class="label">${a}${icon(d||'overview')}</div><div class="value">${b}</div><div class="caption">${c}</div></div>`).join('')}</div>`;
function cameraImage(c,large=false){return c.online?`<img src="${[2,3,8].includes(c.id)?'assets/progress-diptych.png':img(c.image)}" class="${[2,3,8].includes(c.id)?'generated-view '+(c.id===8?'earlier':'later'):''}" alt="Illustrative construction view for ${c.name}"><div class="camera-shade"></div><div class="view-top"><span class="view-code">CAM ${String(c.id).padStart(2,'0')}</span><span class="sample-tag">DEMO SNAPSHOT</span></div><div class="view-bottom"><span>${icon('cameras')} ${c.name}</span><span>10:45:00</span></div>`:`<div class="offline-view">${icon('cameras')}<strong>Camera connection lost</strong><small>Last connected at 10:18 · Sample status</small><span class="offline-hint">Network check required</span></div>`}
function camera(c){return `<article class="camera"><button type="button" class="camera-view" data-camera="${c.id}" aria-label="Open ${c.name}">${cameraImage(c)}<span class="expand-cam">${icon('expand')}</span></button><div class="camera-caption"><div><h3>${c.name}</h3><small>${c.zone} · ${c.online?c.people+' people observed':'Monitoring unavailable'}</small></div>${badge(c.online?'Online':'Offline')}</div></article>`}
function event(e){return `<button class="event" data-incident="${e.id}"><span class="event-sign ${e.severity==='High'?'high':''}">${icon('incidents')}</span><span class="event-copy"><span class="event-meta">INC-${e.id}<span>${e.time}</span></span><strong>${e.title}</strong><small>${cams[e.camera-1].name}</small><span class="event-tags">${badge(e.severity)}${badge(e.status,e.status==='Resolved'?'resolved':'')}</span></span><span class="event-arrow">${icon('arrow')}</span></button>`}
function siteMap(){return `<svg viewBox="0 0 680 335" role="group" aria-label="Interactive sample site plan with eight camera locations"><defs><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" fill="none" stroke="#eceae8" stroke-width=".6"/></pattern></defs><rect width="680" height="335" fill="url(#grid)"/><path d="M30 30H650V303H30Z" fill="none" stroke="#beb8b3" stroke-dasharray="5 5"/><path d="M35 265H640M340 38V267" stroke="#e8e6e4" stroke-width="30"/><rect x="66" y="59" width="205" height="151" rx="3" fill="#e6e4e2" stroke="#bbb6b0"/><path d="M95 59v151m30-151v151m30-151v151m30-151v151m30-151v151m30-151v151M66 90h205M66 120h205M66 150h205M66 180h205" stroke="#c9c4c0"/><rect x="98" y="107" width="143" height="43" rx="3" fill="#f7f6f6"/><text x="169" y="125" text-anchor="middle" font-size="15" fill="#3e3c3b" font-family="sans-serif">TOWER A</text><text x="169" y="140" text-anchor="middle" font-size="10" fill="#79746f">Structure · Level 4</text><rect x="401" y="49" width="195" height="78" fill="#e8e7e0" stroke="#c8c6b7"/><text x="499" y="93" text-anchor="middle" font-size="14" fill="#697568">MATERIAL YARD</text><rect x="401" y="150" width="92" height="75" fill="#f3e2ce" stroke="#d6bfa0" stroke-dasharray="4 3"/><text x="447" y="180" text-anchor="middle" font-size="11" fill="#8f6438">EQUIPMENT</text><text x="447" y="197" text-anchor="middle" font-size="10" fill="#8f6438">Restricted zone</text><rect x="516" y="150" width="80" height="75" fill="#e2e9e4" stroke="#b5c3b8"/><text x="556" y="186" text-anchor="middle" font-size="11" fill="#5c7364">TOWER B</text><text x="95" y="294" font-size="12" fill="#7f7a74">MAIN GATE</text><text x="615" y="52" font-size="12" fill="#7f7a74">N ↑</text>${[[64,263],[84,69],[272,211],[594,63],[489,218],[347,295],[642,182],[590,220]].map(([x,y],i)=>`<g role="button" tabindex="0" data-camera="${i+1}" aria-label="${cams[i].name}, ${cams[i].online?'online':'offline'}" style="cursor:pointer"><circle cx="${x}" cy="${y}" r="14" fill="${i===6?'#b95a4c':'#2d6d65'}" stroke="white" stroke-width="3"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="white" font-size="11" font-family="sans-serif">${i+1}</text></g>`).join('')}</svg>`}
function overview(){let open=incidents.filter(e=>e.status!=='Resolved'),c=cams[focusCam-1];return heading('Site overview','A clear view of your site, from the gate to the work floor.',`<button data-action="export">${icon('download')} Site report</button><button class="primary" data-action="simulate">${icon('incidents')} Simulate safety alert</button>`)+`<div class="shift-strip"><span>${icon('clock')} Day shift <b>06:00 – 18:00</b></span><span>${icon('pin')} Riverside Residences · Phase 1</span><span class="snapshot-note">Sample snapshot · 12 Sep, 10:45</span></div>`+stats([['Workforce observed','126','Peak today: 138 · 09:00','workforce'],['Camera availability','7 <small>/ 8</small>','One connection needs attention','cameras'],['Unresolved incidents',open.length,open.filter(e=>e.severity==='High').length+' high priority · Action required','incidents'],['Vehicle entries','24','18 exits recorded this shift','vehicles']])+`<div class="command-grid"><section class="panel monitor-panel"><div class="panel-head"><div><span class="section-kicker">SITE VISIBILITY</span><h2>Camera workspace</h2></div><a class="textbtn" href="#cameras">All 8 cameras ${icon('arrow')}</a></div><div class="monitor-tabs" role="group" aria-label="Featured cameras">${[2,4,8].map(id=>`<button data-focus-cam="${id}" aria-pressed="${id===focusCam}" class="${id===focusCam?'selected':''}">${cams[id-1].name}</button>`).join('')}</div><button class="focus-view" data-camera="${c.id}" aria-label="Open ${c.name}">${cameraImage(c,true)}<span class="expand-cam">${icon('expand')}</span></button><div class="monitor-info"><span><b>${c.people}</b> people observed</span><span>Person · PPE · Zone monitoring</span><span class="monitor-connection">${badge('Online')}</span></div><div class="monitor-timeline"><span>06:00</span><div class="timeline-track"><i style="left:25%"></i><i style="left:56%"></i><i class="red" style="left:74%"></i><i class="red" style="left:86%"></i><b></b></div><span>10:45</span><small>Sample event timeline</small></div></section><section class="panel triage-panel"><div class="panel-head"><div><span class="section-kicker">ACTION CENTRE</span><h2>Needs your attention <span class="count">${open.length}</span></h2></div><a class="textbtn" href="#incidents" aria-label="View all incidents">${icon('arrow')}</a></div>${open.length?open.slice(0,3).map(event).join(''):'<div class="empty">'+icon('check')+'<h3>All caught up</h3><p>No unresolved safety incidents.</p></div>'}<button class="health-alert" data-camera="7"><span>${icon('cameras')}</span><div><strong>East perimeter is offline</strong><small>Coverage interrupted since 10:18</small></div>${icon('arrow')}</button><a class="queue-link" href="#incidents">Open incident register ${icon('arrow')}</a></section></div><div class="lower-grid"><section class="panel coverage-panel"><div class="panel-head"><div><span class="section-kicker">SPATIAL OVERVIEW</span><h2>Site coverage</h2></div><span class="sub">8 locations</span></div><div class="map">${siteMap()}</div><div class="map-legend"><span><i></i>Online</span><span><i class="warn"></i>Offline</span><span>Select a camera to inspect</span></div></section>${workforceChart()}</div>`}
function cameras(){let list=cams.filter(c=>camFilter==='All'||(camFilter==='Online'&&c.online)||(camFilter==='Offline'&&!c.online));return heading('Camera monitoring','Eight viewpoints. One workspace for site visibility.',`<button data-action="camera-export">${icon('download')} Camera health</button>`)+`<div class="camera-summary"><span><b>07</b> Connected cameras</span><span><b class="red">01</b> Connection lost</span><span><b>126</b> People observed</span><span class="sample-inline">Illustrative snapshots · No live feeds</span></div><div class="controls"><div class="filter-tabs" role="group" aria-label="Camera connection filter">${['All','Online','Offline'].map(t=>`<button data-camfilter="${t}" aria-pressed="${t===camFilter}" class="${t===camFilter?'selected':''}">${t}${t==='All'?' cameras':''} <span>${t==='All'?8:t==='Online'?7:1}</span></button>`).join('')}</div><div class="layout-controls"><span class="sub" role="status">${list.length} cameras</span></div></div><div class="camera-grid all">${list.map(camera).join('')}</div>`}
function incidentPage(){const list=incidents.filter(e=>(filter==='All'||e.status===filter)&&`${e.title} ${e.id} ${cams[e.camera-1].name}`.toLowerCase().includes(search.toLowerCase()));return heading('Safety & incidents','Review the evidence, assign an owner and record the response.',`<button class="primary" data-action="simulate">${icon('incidents')} Simulate safety alert</button>`)+stats([['Open',incidents.filter(e=>e.status==='Open').length,'Awaiting first review','incidents'],['In review',incidents.filter(e=>e.status==='In review').length,'Assigned to a site team','workforce'],['Resolved',incidents.filter(e=>e.status==='Resolved').length,'Action recorded','reports'],['High priority',incidents.filter(e=>e.severity==='High'&&e.status!=='Resolved').length,'Unresolved high-priority events','incidents']])+`<div class="controls"><input id="incident-search" type="search" placeholder="Search event, camera or ID" aria-label="Search incidents" value="${esc(search)}"><label for="status-filter">Status</label><select id="status-filter">${['All','Open','In review','Resolved'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><button data-action="filtered-export">${icon('download')} Export results</button></div><section class="panel"><div class="table-scroll"><table class="incident-table"><thead><tr><th>Incident</th><th>Location</th><th>Priority</th><th>Status</th><th>Owner</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${list.map(e=>`<tr><td><strong>${e.title}</strong><small>#INC-${e.id} · ${e.time}</small></td><td data-label="Location">${cams[e.camera-1].name}</td><td data-label="Priority">${badge(e.severity)}</td><td data-label="Status">${badge(e.status,e.status==='Resolved'?'resolved':'')}</td><td data-label="Assigned to">${e.owner}</td><td><button data-incident="${e.id}">Review</button></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">No incidents match these filters.</div>':''}</section>`}
function workforceChart(){return `<section class="panel workforce-panel"><div class="panel-head"><div><span class="section-kicker">WORKFORCE TREND</span><h2>Presence through the shift</h2></div><span class="chart-key"><i></i> People observed</span></div><div class="chart-summary"><strong>126</strong><span>currently observed<br><b>138</b> peak at 09:00</span></div><div class="chart"><svg viewBox="0 0 660 220" role="img" aria-label="Sample observed workforce: 22 at 6 AM, 74 at 7 AM, 113 at 8 AM, 138 at 9 AM, 126 at 10 AM"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b97751" stop-opacity=".25"/><stop offset="1" stop-color="#b97751" stop-opacity=".01"/></linearGradient></defs>${[20,70,120,170].map((y,i)=>`<line x1="43" x2="635" y1="${y}" y2="${y}" stroke="#edebe9" stroke-dasharray="4 5"/><text x="30" y="${y+4}" text-anchor="end" font-size="12" fill="#908b85">${150-i*50}</text>`).join('')}<path d="M43 148 L191 96 L339 57 L487 32 L635 44 L635 170 L43 170Z" fill="url(#chart-fill)"/><path d="M43 148L191 96L339 57L487 32L635 44" fill="none" stroke="#a16545" stroke-width="3"/>${[[43,148,22],[191,96,74],[339,57,113],[487,32,138],[635,44,126]].map(([x,y,n],i)=>`<circle cx="${x}" cy="${y}" r="5" stroke="white" stroke-width="3" fill="#a16545"><title>${String(i+6).padStart(2,'0')}:00 · ${n} people</title></circle><text x="${x}" y="205" text-anchor="middle" font-size="12" fill="#87817b">${String(i+6).padStart(2,'0')}:00</text>`).join('')}</svg></div><div class="chart-foot"><span>Visible counts only</span><a href="#workforce" class="textbtn">Explore zones ${icon('arrow')}</a></div></section>`}
function workforce(){return heading('Workforce presence','Zone observations support supervision; they are not verified attendance.')+stats([['People observed','126','Current sample count','workforce'],['Peak visible count','138','09:00 sample','progress'],['Active zones','7','One camera offline','cameras'],['Shift started','06:00','Sample day shift','reports']])+workforceChart()+`<section class="panel"><div class="panel-head"><h2>Presence by zone</h2><span class="sub">No personal identification</span></div><div class="table-scroll"><table><thead><tr><th>Camera / zone</th><th>Visible people</th><th>Coverage</th></tr></thead><tbody>${cams.map(c=>`<tr><td>${c.name}</td><td>${c.online?c.people:'Unavailable'}</td><td>${badge(c.online?'Online':'Offline')}</td></tr>`).join('')}</tbody></table></div></section>`}
const vehicles=[['10:41','Concrete mixer','Main gate','Entry','Delivery'],['10:32','Tipper truck','Main gate','Exit','Material transport'],['10:19','Light vehicle','Main gate','Entry','Site access'],['10:11','Tipper truck','Main gate','Entry','Material transport'],['09:54','Concrete mixer','Main gate','Exit','Delivery complete']];
function vehiclePage(){return heading('Vehicles & equipment','Sample movement records and visible equipment activity.')+stats([['Vehicle entries','24','From start of shift','vehicles'],['Vehicle exits','18','From start of shift','vehicles'],['Equipment observed','6','Across configured zones','cameras'],['Loading events','9','Sample material-handling events','reports']])+`<div class="overview-grid"><section class="panel"><div class="panel-head"><h2>Recent gate movements</h2></div><div class="table-scroll"><table><thead><tr><th>Time</th><th>Vehicle</th><th>Movement</th></tr></thead><tbody>${vehicles.map(v=>`<tr><td>${v[0]}</td><td>${v[1]}<small>${v[4]}</small></td><td>${badge(v[3])}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Equipment activity</h2></div>${[['Excavator','Tower B foundation','Movement observed'],['Tower crane','Tower A','Movement observed'],['Loader','Material yard','No movement in sample']].map(v=>`<div class="milestone"><strong>${v[0]}</strong><p>${v[1]}</p>${badge(v[2])}</div>`).join('')}</section></div><div class="notice">Movement indicates visible activity, not engine hours or fuel use. Number plate recognition is not enabled in this demo.</div>`}
function progress(){return heading('Site progress','Dated records and milestone review for the project team.')+`<div class="notice">Generated sample imagery demonstrates a fixed-view progress comparison. Dates and milestones are illustrative, not records of an actual project.</div><div class="progress-layout"><section class="panel"><div class="panel-head"><h2>Tower A · North elevation</h2><span class="badge">Sample comparison</span></div><div class="progress-picture"><div class="progress-current"></div><div class="comparison"></div><span class="left">29 Aug · Sample baseline</span><span class="right">12 Sep · Sample update</span></div><div class="slider-control"><label for="compare">Compare views</label><input id="compare" type="range" min="0" max="100" value="50" aria-label="Comparison divider"></div></section><section class="panel"><div class="panel-head"><h2>Milestone register</h2></div>${[['Foundation','Completed','100'],['Tower A structure','In progress','62'],['Masonry','In progress','28']].map(v=>`<div class="milestone"><strong>${v[0]}</strong><p>${v[1]} <b class="milestone-percent">${v[2]}%</b></p><small>Owner: Project manager · Sample planning entry</small><div class="bar"><span style="width:${v[2]}%"></span></div></div>`).join('')}<div class="milestone sub">Illustrative planning values entered by a project manager; not AI-certified completion.</div></section></div>`}
function reports(){return heading('Site reports','Download sample records for a daily review or client walkthrough.')+`<div class="report-grid">${[['Daily site summary','Workforce, camera health, vehicles and incident status.','export'],['Safety incident register','Event details, priority, ownership, notes and resolution.','incident-export'],['Camera health report','All eight camera locations and their sample connection status.','camera-export']].map(([t,d,a])=>`<section class="panel report">${icon('reports')}<h2>${t}</h2><p>${d}</p><button class="primary" data-action="${a}">Download CSV</button></section>`).join('')}</div><div class="notice">Exports contain demonstration data from the current session. Resolve an incident and download again to see the updated status.</div>`}
function render(){active=location.hash.slice(1)||'overview';if(!views[active])active='overview';$('nav').innerHTML=Object.entries(views).map(([k,v])=>`<a href="#${k}" class="${active===k?'active':''}" ${active===k?'aria-current="page"':''}>${icon(k)}<span>${v}</span>${k==='incidents'?'<b class="nav-count">'+incidents.filter(e=>e.status!=='Resolved').length+'</b>':''}</a>`).join('');$('#crumb').textContent=views[active];$('#main').dataset.view=active;$('#main').innerHTML=({overview,cameras,incidents:incidentPage,workforce,vehicles:vehiclePage,progress,reports}[active])();closeNav();}
function showDialog(content){$('#detail').classList.remove('incident-dialog','camera-dialog');$('#dialog-content').innerHTML=content;$('#detail').setAttribute('aria-labelledby','modal-title');if(!$('#detail').open)$('#detail').showModal()}
function closeDialog(){ $('#detail').close();$('#dialog-content').innerHTML=''; }
const modalHead=(title,sub)=>`<div class="modal-head"><div><div class="eyebrow">SRS Logics · Demo</div><h2 id="modal-title">${title}</h2><p class="sub">${sub}</p></div><button class="iconbtn" data-close aria-label="Close dialog">×</button></div>`;
function openCamera(id){let c=cams[id-1];showDialog(modalHead(c.name,`Camera ${String(id).padStart(2,'0')} · ${c.zone}`)+`<div class="camera-detail-grid"><div><div class="camera-evidence">${cameraImage(c,true)}</div><div class="evidence-caption">Illustrative image · No live video or AI processing</div></div><div class="camera-side"><span class="section-kicker">CAMERA HEALTH</span><h3>${c.online?'Connection available':'Connection interrupted'}</h3><dl><div><dt>Connection</dt><dd>${badge(c.online?'Online':'Offline')}</dd></div><div><dt>Visible people</dt><dd>${c.online?c.people:'Unavailable'}</dd></div><div><dt>Location</dt><dd>${c.zone}</dd></div><div><dt>Last sample update</dt><dd>${c.online?'10:45:00':'10:18:00'}</dd></div></dl><span class="section-kicker">CONFIGURED CHECKS</span><div class="check-list"><span>${icon('check')} Person detection</span><span>${icon('check')} ${c.zone==='Gate & access'?'Vehicle movement':'PPE compliance'}</span><span>${icon('check')} Zone monitoring</span></div>${!c.online?'<button data-action="camera-check">Run connection check</button>':''}<div class="camera-related"><h3>Related incidents</h3>${incidents.filter(e=>e.camera===id).length?incidents.filter(e=>e.camera===id).map(e=>`<button data-incident="${e.id}">${e.title}${icon('arrow')}</button>`).join(''):'<p>No sample incidents for this camera.</p>'}</div></div></div>`);$('#detail').classList.add('camera-dialog')}
function openIncident(id){let e=incidents.find(x=>x.id===id),c=cams[e.camera-1];showDialog(modalHead(e.title,`INC-${e.id} · ${c.name} · 12 September, ${e.time}`)+`<div class="incident-workspace"><div class="incident-evidence"><div class="camera-evidence">${cameraImage(c,true)}</div><div class="evidence-caption">Sample event evidence · Alert is illustrative, not inferred from this image.</div><div class="evidence-info"><div><span class="section-kicker">DETECTION</span><strong>${e.title.includes('helmet')?'PPE · Helmet check':e.title.includes('zone')?'Restricted-area entry':'Site activity observation'}</strong></div><div><span class="section-kicker">PRIORITY</span>${badge(e.severity)}</div></div><div class="history"><h3>Activity history</h3>${e.history.map(h=>`<div class="history-item"><span></span><p>${esc(h)}</p></div>`).join('')}</div></div><form class="incident-review" id="incident-form" data-id="${id}"><div class="review-top"><span class="section-kicker">REVIEW & RESPONSE</span>${badge(e.status,e.status==='Resolved'?'resolved':'')}</div><h3>${e.status==='Resolved'?'Resolution recorded':'Take the next step'}</h3><p class="sub">${e.status==='Resolved'?'Notes and ownership can be updated without reopening the incident.':'Review the observation and record your response.'}</p><label for="owner">Incident owner</label><select id="owner">${['Safety officer','Site manager','Security supervisor'].map(o=>`<option ${o===e.owner?'selected':''}>${o}</option>`).join('')}</select><label for="note">${e.status==='Resolved'?'Resolution note':'Action taken / review note'}</label><textarea id="note" placeholder="Describe the check or corrective action…">${esc(e.note)}</textarea><div class="note-help">An action note is required to resolve an incident.</div><div class="modal-actions"><button type="submit" name="intent" value="review">Save ${e.status==='Resolved'?'changes':'review'}</button>${e.status!=='Resolved'?'<button type="submit" name="intent" value="resolve" class="primary">'+icon('check')+' Mark resolved</button>':'<button type="submit" name="intent" value="reopen">Reopen incident</button>'}</div><div class="review-policy">${icon('incidents')} Human review is required before action. This demo does not notify site personnel.</div></form></div>`);$('#detail').classList.add('incident-dialog')}
function exportIncidents(rows){csv('sample-incidents.csv',[['DEMO Incident ID','Date','Time','Event','Camera','Priority','Status','Owner','Note','History'],...rows.map(e=>[e.id,'2026-09-12',e.time,e.title,cams[e.camera-1].name,e.severity,e.status,e.owner,e.note,e.history.join(' | ')])]);}
function csv(name,rows){const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Sample report downloaded')}
function action(a){if(a==='filtered-export'){const rows=incidents.filter(e=>(filter==='All'||e.status===filter)&&`${e.title} ${e.id} ${cams[e.camera-1].name}`.toLowerCase().includes(search.toLowerCase()));exportIncidents(rows);return;}if(a==='simulate'){seq++;incidents.unshift({id:seq,title:'Possible missing safety helmet',camera:3,severity:'High',status:'Open',time:'10:45',owner:'Safety officer',note:'',history:['10:45 · Event added using demo simulation']});persist();render();openIncident(seq);toast('Sample safety alert created')}if(a==='export')csv('sample-site-summary.csv',[['SRS Logics - DEMONSTRATION DATA'],['Site','Riverside Residences'],['Date','2026-09-12'],['Workers observed',126],['Cameras online',7],['Cameras total',8],['Unresolved incidents',incidents.filter(x=>x.status!=='Resolved').length],['Vehicle entries',24],['Vehicle exits',18]]);if(a==='incident-export')exportIncidents(incidents);if(a==='camera-export')csv('sample-camera-health.csv',[['DEMO Camera','Location','Status','Visible people'],...cams.map(c=>[c.id,c.name,c.online?'Online':'Offline',c.online?c.people:'Unavailable'])]);if(a==='camera-check')toast('Demo check: connection unavailable. Site network requires review.')}
document.addEventListener('click',e=>{const i=e.target.closest('[data-incident]'),c=e.target.closest('[data-camera]'),a=e.target.closest('[data-action]');if(i)openIncident(+i.dataset.incident);else if(c)openCamera(+c.dataset.camera);else if(a)action(a.dataset.action);if(e.target.closest('[data-close]'))closeDialog();if(e.target.closest('.menu'))openNav();if(e.target.closest('[data-nav-close]'))closeNav();if(e.target.closest('.reset'))showDialog(modalHead('Reset this demo?','Restore the original sample data')+'<div class="modal-body"><p>Your incident reviews and added alerts will be cleared from this browser session.</p><div class="modal-actions"><button data-close>Keep working</button><button class="primary" data-confirm-reset>Reset demo</button></div></div>');if(e.target.closest('#credits'))showDialog(modalHead('Image credits','Illustrative construction photography')+`<div class="modal-body" id="credits-body"><p>Photographs are for demonstration only and do not show this sample project. The progress comparison and selected tower views use AI-generated sample imagery.</p><div id="credit-links"></div></div>`)});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){filter=e.target.value;render();$('#status-filter').focus()}if(e.target.id==='camera-status'){camFilter=e.target.value;render();$('#camera-status').focus()}});
document.addEventListener('input',e=>{if(e.target.id==='incident-search'){let pos=e.target.selectionStart;search=e.target.value;render();$('#incident-search').focus();$('#incident-search').setSelectionRange(pos,pos)}if(e.target.id==='compare'){$('.comparison').style.clipPath=`inset(0 ${100-e.target.value}% 0 0)`;$('.progress-picture').style.setProperty('--divider',e.target.value+'%')}});
document.addEventListener('submit',e=>{if(e.target.id!=='incident-form')return;e.preventDefault();let item=incidents.find(x=>x.id===+e.target.dataset.id),note=$('#note').value.trim(),status=e.submitter.value==='resolve'?'Resolved':e.submitter.value==='reopen'?'Open':item.status==='Resolved'?'Resolved':'In review';if(status==='Resolved'&&!note){$('#note').setCustomValidity('Add an action note before resolving this incident.');$('#note').reportValidity();$('#note').oninput=()=>$('#note').setCustomValidity('');return}item.owner=$('#owner').value;item.note=note;item.status=status;item.history.push(`10:45 · ${status} · ${item.owner}${note?' · '+note:''}`);persist();closeDialog();render();toast(status==='Resolved'?'Incident resolved. Dashboard and reports updated.':'Review saved and owner assigned.')});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-camera]')){e.preventDefault();openCamera(+e.target.dataset.camera)}});window.addEventListener('hashchange',render);render();
document.addEventListener('click',e=>{if(e.target.closest('#credits'))$('#credit-links').innerHTML=`<p><a href="https://commons.wikimedia.org/wiki/File:Construction_site_excavator_and_truck.jpg" target="_blank" rel="noreferrer">Excavator and truck — Neb / Wikimedia Commons</a><br><a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a> · Resized; display colour treatment and cropping.</p><p><a href="https://unsplash.com/photos/a-crane-is-standing-on-top-of-a-building-under-construction-vWYx6v8J-x8" target="_blank" rel="noreferrer">Construction crane — d c / Unsplash</a></p><p><a href="https://unsplash.com/photos/a-building-under-construction-with-a-crane-on-top-of-it-tEibU_Eqbj0" target="_blank" rel="noreferrer">Building under construction — shraga kopstein / Unsplash</a></p><p>Unsplash images used under the <a href="https://unsplash.com/license" target="_blank" rel="noreferrer">Unsplash License</a>. Camera views reuse these illustrative images.</p>`});

function openNav(){document.body.classList.add('nav-open');$('.menu').setAttribute('aria-expanded','true');$('aside').inert=false;$('.nav-close').focus();}
function closeNav(){document.body.classList.remove('nav-open');$('.menu').setAttribute('aria-expanded','false');$('aside').inert=window.innerWidth<=640;}
window.addEventListener('resize',closeNav);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('nav-open')){closeNav();$('.menu').focus();}});
document.addEventListener('click',e=>{const c=e.target.closest('[data-focus-cam]'),f=e.target.closest('[data-camfilter]');if(c){focusCam=+c.dataset.focusCam;render();document.querySelector('[data-focus-cam="'+focusCam+'"]').focus();}if(f){camFilter=f.dataset.camfilter;render();document.querySelector('[data-camfilter="'+camFilter+'"]').focus();}if(e.target.closest('[data-confirm-reset]')){incidents=structuredClone(initial);seq=1042;filter='All';search='';camFilter='All';persist();closeDialog();render();toast('Original demo restored.');}});
$('#detail').addEventListener('cancel',()=>setTimeout(()=>{$('#dialog-content').innerHTML='';},0));
